// SourceStageRequirements returns the full canonical requirement registry.
func SourceStageRequirements() []SourceStageRequirement { return sourceStageRequirements }

// SourceStageRequirementByID returns the requirement with the given ID.
func SourceStageRequirementByID(id string) (SourceStageRequirement, bool) {
	for _, r := range sourceStageRequirements {
		if r.RequirementID == id {
			return r, true
		}
	}
	return SourceStageRequirement{}, false
}

// SourceStageDocuments returns the normative documents referenced by the registry.
func SourceStageDocuments() []SourceStageDocument { return sourceStageDocuments }

// SourceStageDocumentHash returns the recorded SHA-256 of a normative document.
func SourceStageDocumentHash(name string) (string, bool) {
	for _, d := range sourceStageDocuments {
		if d.Name == name {
			return d.SHA256, true
		}
	}
	return "", false
}

